(()=>{let showing=false;const dialog=document.createElement('dialog');dialog.style.cssText='border:1px solid #35527d;border-radius:18px;background:#101c30;color:#e9efff;padding:28px;max-width:560px;width:92vw;max-height:85vh;overflow:auto';const title=document.createElement('h2'),body=document.createElement('p'),image=document.createElement('img'),save=document.createElement('a'),close=document.createElement('button');body.style.whiteSpace='pre-wrap';image.style.cssText='max-width:100%;max-height:50vh;object-fit:contain';save.textContent='บันทึกรูป';save.style.cssText='display:inline-block;color:#8dc7ff;margin:16px';close.textContent='รับทราบ';close.style.cssText='background:#2677f3;color:white;border:0;border-radius:8px;padding:10px 18px;cursor:pointer';dialog.append(title,body,image,save,close);document.body.append(dialog);
async function poll(){if(showing||document.hidden)return;try{const r=await fetch('/np/announcements');if(!r.ok)return;const d=await r.json();for(const n of d.items){const key='np-news:'+d.viewer+':'+n.id+':'+n.updated_at;if(localStorage.getItem(key))continue;showing=true;title.textContent=n.title;body.textContent=n.body;image.hidden=!n.image;save.hidden=!n.image;if(n.image){image.src=n.image;image.alt=n.title;save.href=n.image;save.download='NP-announcement-'+n.id+'.'+(n.image.startsWith('data:image/jpeg')?'jpg':n.image.startsWith('data:image/webp')?'webp':'png');}const ack=()=>{localStorage.setItem(key,'1');showing=false;dialog.close();};close.onclick=ack;dialog.oncancel=e=>{e.preventDefault();ack();};dialog.showModal();break;}}catch{}}
setInterval(poll,15000);poll();})();
